fn largest_smallest_integers(arr: Vec<i8>) -> (Option<i8>, Option<i8>) {
    if arr.is_empty() {
        return (None, None);
    }

    // Initialize both min and max to the first element
    let mut max_val = arr[0];
    let mut min_val = arr[0];

    // Iterate over the rest of the elements and update min and max
    for &x in &arr[1..] {
        if x > max_val {
            max_val = x;
        }
        if x < min_val {
            min_val = x;
        }
    }

    (Some(max_val), Some(min_val))
}

